def _build(tree):
    if not tree or tree[0] is None:
        return None
    nodes = [None if v is None else {'val': v, 'left': None, 'right': None} for v in tree]
    kids = iter(range(1, len(nodes)))
    for node in nodes:
        if node is None:
            continue
        for side in ('left', 'right'):
            idx = next(kids, None)
            if idx is not None and idx < len(nodes) and nodes[idx] is not None:
                node[side] = nodes[idx]
    return nodes[0]


def has_path_sum(tree, target):
    root = _build(tree)
    if root is None:
        return False

    def dfs(node, remaining):
        if node['left'] is None and node['right'] is None:
            return remaining == node['val']
        found = False
        if node['left']:
            found = found or dfs(node['left'], remaining - node['val'])
        if node['right']:
            found = found or dfs(node['right'], remaining - node['val'])
        return found

    return dfs(root, target)
